// Single source of truth for species icon slugs and URLs.
// (Was previously reimplemented inline in four components.)

export function speciesSlug(name: string): string {
    return name.toLowerCase().replace(/ /g, '_');
}

// 1024px WebP derivatives generated by art-pipeline/make_web_icons.py —
// ~60-150 KB each vs up to 3.8 MB for the PNG masters they replace.
export function speciesIconUrl(name: string): string {
    return `/icons/web/${speciesSlug(name)}.webp`;
}
